1	/**
2	 * Notion MCP Client Extension for pi
3	 *
4	 * Connects to the official Notion MCP server at https://mcp.notion.com/mcp
5	 * using OAuth authentication.
6	 *
7	 * Usage:
8	 *   /notion                    - Status, connect, or disconnect
9	 *   "Search my Notion for X"    - Natural language (tools auto-discovered after connect)
10	 */
11	
12	import { createHash, randomBytes } from "node:crypto";
13	import { existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from "node:fs";
14	import { createServer } from "node:net";
15	import { homedir } from "node:os";
16	import { dirname, isAbsolute, join, resolve } from "node:path";
17	import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
18	import { getPort as lookupPort } from "portfinder";
19	import { Type } from "typebox";
20	
21	// =============================================================================
22	// Constants
23	// =============================================================================
24	
25	const NOTION_MCP_URL = "https://mcp.notion.com/mcp";
26	const HTTP_REQUEST_COMPLETE_MARKER = "\r\n\r\n";
27	const CALLBACK_PATH_PREFIX = "GET /callback?";
28	const OAUTH_CALLBACK_HOST = "127.0.0.1";
29	const NOTION_MCP_AUTH_FILE_ENV = "NOTION_MCP_AUTH_FILE";
30	const NOTION_MCP_AUTH_FILE_LEGACY_ENV = "NOTION_MCP_AUTH";
31	
32	function getHomeDir(): string {
33	  return process.env.HOME || homedir();
34	}
35	
36	type NotifyLevel = "info" | "error";
37	type NotifyFn = (message: string, type?: NotifyLevel) => void;
38	
39	type ToolExecutionResult = {
40	  content: Array<{ type: "text"; text: string }>;
41	  isError?: boolean;
42	  details: Record<string, unknown>;
43	};
44	
45	// =============================================================================
46	// Types
47	// =============================================================================
48	
49	interface MCPTool {
50	  name: string;
51	  description: string;
52	  inputSchema: Record<string, unknown>;
53	}
54	
55	interface MCPClientState {
56	  connected: boolean;
57	  authenticated: boolean;
58	  sessionId: string | null;
59	  accessToken: string | null;
60	  mcpUrl: string | null;
61	}
62	
63	// =============================================================================
64	// OAuth Callback Server
65	// =============================================================================
66	
67	interface OAuthCallbackResult {
68	  code?: string;
69	  accessToken?: string;
70	  error?: string;
71	  errorDescription?: string;
72	}
73	
74	interface OAuthCallbackServerResult {
75	  port: number;
76	  result: Promise<OAuthCallbackResult>;
77	}
78	
79	function buildHtmlResponse(statusLine: string, html: string): string {
80	  return `${statusLine}\r\nContent-Length: ${html.length}\r\nContent-Type: text/html\r\n\r\n${html}`;
81	}
82	
83	function buildOAuthCallbackUrl(port: number): string {
84	  return `http://${OAUTH_CALLBACK_HOST}:${port}/callback`;
85	}
86	
87	function writeHtmlResponse(socket: NodeJS.WritableStream, statusLine: string, html: string): void {
88	  socket.write(buildHtmlResponse(statusLine, html));
89	}
90	
91	function extractCallbackParams(buffer: string): URLSearchParams | null {
92	  if (!buffer.includes(HTTP_REQUEST_COMPLETE_MARKER)) return null;
93	
94	  const requestLine = buffer.split("\r\n", 1)[0] ?? "";
95	  if (!requestLine.startsWith(CALLBACK_PATH_PREFIX)) return null;
96	
97	  const queryString = requestLine.slice(CALLBACK_PATH_PREFIX.length).split(" ", 1)[0] ?? "";
98	  return new URLSearchParams(queryString);
99	}
100	
101	function resolveCallbackResult(
102	  params: URLSearchParams,
103	  expectedState: string,
104	): {
105	  response: { statusLine: string; html: string };
106	  result: OAuthCallbackResult;
107	} {
108	  if (params.get("state") !== expectedState) {
109	    return {
110	      response: {
111	        statusLine: "HTTP/1.1 400 Bad Request",
112	        html: `<html><body><h1>State mismatch</h1><p>Please try again.</p></body></html>`,
113	      },
114	      result: { error: "State mismatch" },
115	    };
116	  }
117	
118	  const error = params.get("error");
119	  if (error) {
120	    return {
121	      response: {
122	        statusLine: "HTTP/1.1 400 Bad Request",
123	        html: `<html><body><h1>Authorization failed</h1><p>Error: ${error}</p><p>${params.get("error_description") || ""}</p></body></html>`,
124	      },
125	      result: {
126	        error,
127	        errorDescription: params.get("error_description") || undefined,
128	      },
129	    };
130	  }
131	
132	  const accessToken = params.get("access_token");
133	  if (accessToken) {
134	    return {
135	      response: {
136	        statusLine: "HTTP/1.1 200 OK",
137	        html: `<html><body><h1>Authorized!</h1><p>You can close this window.</p><script>window.close();</script></body></html>`,
138	      },
139	      result: { accessToken },
140	    };
141	  }
142	
143	  const code = params.get("code");
144	  if (code) {
145	    return {
146	      response: {
147	        statusLine: "HTTP/1.1 200 OK",
148	        html: `<html><body><h1>Authorized!</h1><p>You can close this window.</p><script>window.close();</script></body></html>`,
149	      },
150	      result: { code },
151	    };
152	  }
153	
154	  return {
155	    response: {
156	      statusLine: "HTTP/1.1 400 Bad Request",
157	      html: `<html><body><h1>Authorization failed</h1><p>No code or token in callback.</p></body></html>`,
158	    },
159	    result: { error: "No code or token in callback" },
160	  };
161	}
162	
163	async function startOAuthCallbackServer(
164	  preferredPort: number,
165	  state: string,
166	  timeoutMs = 300000,
167	): Promise<OAuthCallbackServerResult> {
168	  const port = await lookupPort({ port: preferredPort });
169	
170	  const resultPromise = new Promise<OAuthCallbackResult>((resolve, reject) => {
171	    const server = createServer();
172	    const finish = (result: OAuthCallbackResult) => {
173	      clearTimeout(timeout);
174	      server.close();
175	      resolve(result);
176	    };
177	    const timeout = setTimeout(() => {
178	      server.close();
179	      reject(new Error("OAuth callback timed out (5 minutes)"));
180	    }, timeoutMs);
181	
182	    server.on("connection", (socket) => {
183	      let buffer = "";
184	
185	      socket.on("data", (chunk) => {
186	        buffer += chunk.toString();
187	        const params = extractCallbackParams(buffer);
188	        if (!params) return;
189	
190	        const { response, result } = resolveCallbackResult(params, state);
191	        writeHtmlResponse(socket, response.statusLine, response.html);
192	        socket.end();
193	        finish(result);
194	      });
195	
196	      socket.on("error", () => {});
197	    });
198	
199	    server.on("error", (err: NodeJS.ErrnoException) => {
200	      clearTimeout(timeout);
201	      reject(new Error(`Callback server error: ${err.message}`));
202	    });
203	
204	    server.listen(port, OAUTH_CALLBACK_HOST, () => {});
205	  });
206	
207	  return { port, result: resultPromise };
208	}
209	
210	// =============================================================================
211	// Dynamic Client Registration (RFC 7591)
212	// =============================================================================
213	
214	interface ClientRegistration {
215	  client_id: string;
216	  client_secret?: string;
217	}
218	
219	async function registerClient(redirectUri: string): Promise<ClientRegistration> {
220	  const response = await fetch("https://mcp.notion.com/register", {
221	    method: "POST",
222	    headers: {
223	      "Content-Type": "application/json",
224	    },
225	    body: JSON.stringify({
226	      redirect_uris: [redirectUri],
227	      token_endpoint_auth_method: "client_secret_post",
228	      grant_types: ["authorization_code", "refresh_token"],
229	      response_types: ["code"],
230	      client_name: "pi-notion",
231	    }),
232	  });
233	
234	  if (!response.ok) {
235	    const error = await response.text();
236	    throw new Error(`Client registration failed: ${response.status} - ${error}`);
237	  }
238	
239	  return (await response.json()) as ClientRegistration;
240	}
