242	// =============================================================================
243	// Token Exchange
244	// =============================================================================
245	
246	async function exchangeCodeForToken(
247	  code: string,
248	  redirectUri: string,
249	  codeVerifier: string,
250	  clientId: string,
251	  clientSecret?: string,
252	): Promise<{ accessToken: string }> {
253	  const params: Record<string, string> = {
254	    grant_type: "authorization_code",
255	    client_id: clientId,
256	    code,
257	    redirect_uri: redirectUri,
258	    code_verifier: codeVerifier,
259	  };
260	  if (clientSecret) {
261	    params.client_secret = clientSecret;
262	  }
263	  const body = new URLSearchParams(params);
264	  const response = await fetch("https://mcp.notion.com/token", {
265	    method: "POST",
266	    headers: {
267	      "Content-Type": "application/x-www-form-urlencoded",
268	    },
269	    body: body.toString(),
270	  });
271	
272	  if (!response.ok) {
273	    const error = await response.text();
274	    throw new Error(`Token exchange failed: ${response.status} - ${error}`);
275	  }
276	
277	  const data = (await response.json()) as { access_token: string };
278	  return { accessToken: data.access_token };
279	}
280	
281	function createPkceChallenge(): { codeVerifier: string; codeChallenge: string } {
282	  const codeVerifier = randomBytes(32).toString("base64url");
283	  const codeChallenge = createHash("sha256").update(codeVerifier).digest("base64url");
284	  return { codeVerifier, codeChallenge };
285	}
286	
287	function buildAuthorizationUrl(
288	  registration: ClientRegistration,
289	  callbackUrl: string,
290	  codeChallenge: string,
291	  state: string,
292	): string {
293	  const authUrl = new URL("https://mcp.notion.com/authorize");
294	  authUrl.searchParams.set("response_type", "code");
295	  authUrl.searchParams.set("client_id", registration.client_id);
296	  authUrl.searchParams.set("redirect_uri", callbackUrl);
297	  authUrl.searchParams.set("code_challenge", codeChallenge);
298	  authUrl.searchParams.set("code_challenge_method", "S256");
299	  authUrl.searchParams.set("state", state);
300	  authUrl.searchParams.set("prompt", "consent");
301	  return authUrl.toString();
302	}
303	
304	async function resolveAccessToken(
305	  callbackResult: OAuthCallbackResult,
306	  callbackUrl: string,
307	  codeVerifier: string,
308	  registration: ClientRegistration,
309	  notify: NotifyFn,
310	): Promise<string> {
311	  if (callbackResult.error) {
312	    throw new Error(`Authorization failed: ${callbackResult.error}`);
313	  }
314	
315	  if (callbackResult.accessToken) {
316	    return callbackResult.accessToken;
317	  }
318	
319	  if (!callbackResult.code) {
320	    throw new Error("No authorization code received");
321	  }
322	
323	  notify("Exchanging authorization code for token...");
324	  const tokenResult = await exchangeCodeForToken(
325	    callbackResult.code,
326	    callbackUrl,
327	    codeVerifier,
328	    registration.client_id,
329	    registration.client_secret,
330	  );
331	  return tokenResult.accessToken;
332	}
