547	function resolveAuthFilePath(path: string): string {
548	  const trimmed = path.trim();
549	  if (trimmed.startsWith("~/")) {
550	    return join(getHomeDir(), trimmed.slice(2));
551	  }
552	  if (trimmed.startsWith("~")) {
553	    return join(getHomeDir(), trimmed.slice(1));
554	  }
555	  if (isAbsolute(trimmed)) {
556	    return trimmed;
557	  }
558	  return resolve(process.cwd(), trimmed);
559	}
