735	async function connectWithSavedConfig(client: NotionMCPClient, notify: NotifyFn): Promise<boolean> {
736	  const savedConfig = await storage.load();
737	  if (!savedConfig) return false;
738	
739	  notify("Connecting to saved Notion MCP...");
740	  try {
741	    await client.connect(savedConfig.mcpUrl, savedConfig.accessToken);
742	    return true;
743	  } catch (error) {
744	    const message = error instanceof Error ? error.message : String(error);
745	    notify(`Connection failed: ${message}`, "error");
746	    await storage.clear();
747	    return false;
748	  }
749	}
