751	async function performOAuthConnection(notify: NotifyFn): Promise<OAuthConnectionData> {
752	  const state = randomBytes(16).toString("hex");
753	  const callbackServer = await startOAuthCallbackServer(3000, state);
754	  const callbackUrl = buildOAuthCallbackUrl(callbackServer.port);
755	
756	  notify("Registering OAuth client...");
757	  const registration = await registerClient(callbackUrl);
758	  const { codeVerifier, codeChallenge } = createPkceChallenge();
759	  const authUrl = buildAuthorizationUrl(registration, callbackUrl, codeChallenge, state);
760	
761	  notify("Opening Notion authorization page...");
762	  await openBrowser(authUrl);
763	  notify("Waiting for authorization callback...");
764	
765	  const callbackResult = await callbackServer.result;
766	  const accessToken = await resolveAccessToken(callbackResult, callbackUrl, codeVerifier, registration, notify);
767	  return { accessToken, registration };
768	}
