788	async function ensureConnected(
789	  client: NotionMCPClient,
790	  registerMCPTools: () => void,
791	  notify: NotifyFn,
792	): Promise<{ reusedSavedConfig: boolean }> {
793	  const connectedFromSavedConfig = await connectWithSavedConfig(client, notify);
794	  if (connectedFromSavedConfig) {
795	    registerMCPTools();
796	    return { reusedSavedConfig: true };
797	  }
798	
799	  const { accessToken, registration } = await performOAuthConnection(notify);
800	  await finalizeConnection(client, registration, accessToken, registerMCPTools, notify);
801	  return { reusedSavedConfig: false };
802	}
