838	export default function notionMCPClientExtension(pi: ExtensionAPI) {
839	  pi.registerFlag("--notion-mcp-auth-file", {
840	    description: "Path to the persisted Notion MCP auth file.",
841	    type: "string",
842	  });
843	  pi.registerFlag("--notion-mcp-auth", {
844	    description: "Deprecated alias for --notion-mcp-auth-file.",
845	    type: "string",
846	  });
847	
848	  const authFileFlag = pi.getFlag("--notion-mcp-auth-file");
849	  const legacyAuthFileFlag = pi.getFlag("--notion-mcp-auth");
850	  if (typeof authFileFlag === "string" && authFileFlag.trim().length > 0) {
851	    process.env.NOTION_MCP_AUTH_FILE = authFileFlag;
852	  } else if (typeof legacyAuthFileFlag === "string" && legacyAuthFileFlag.trim().length > 0) {
853	    console.warn("[pi-notion] --notion-mcp-auth is deprecated; use --notion-mcp-auth-file.");
854	    process.env.NOTION_MCP_AUTH_FILE = legacyAuthFileFlag;
855	  }
856	
857	  mcpClient = new NotionMCPClient();
858	  const notify = createUiNotifier(pi);
859	
860	  // Register dynamic MCP tools after connection
861	  const registerMCPTools = () => {
862	    if (!mcpClient?.state.mcpUrl) return;
863	
864	    const tools = mcpClient.getTools();
865	    const mcpUrl = mcpClient.state.mcpUrl;
866	
867	    for (const tool of tools) {
868	      if (pi.getAllTools().find((t) => t.name === tool.name)) continue;
869	
870	      pi.registerTool({
871	        name: tool.name,
872	        label: `Notion: ${tool.name.replace(/_/g, " ")}`,
873	        description: tool.description || `Notion MCP tool: ${tool.name}`,
874	        parameters: Type.Unsafe(tool.inputSchema),
875	        execute: createRegisteredToolExecutor(mcpClient, mcpUrl, tool),
876	      });
877	    }
878	
879	    if (tools.length > 0) {
880	      notify(`Registered ${tools.length} Notion MCP tools!`);
881	    }
882	  };
883	
884	  // /notion command
885	  pi.registerCommand("notion", {
886	    description: "Connect to Notion MCP, show status, or disconnect",
887	    async handler(_args, ctx) {
888	      if (!mcpClient) {
889	        ctx.ui.notify("Notion MCP not initialized", "error");
890	        return;
891	      }
892	
893	      if (!mcpClient.state.connected) {
